import React from 'react';
import { Zap, Moon, Sun, History, HardDrive, Settings2, FolderTree } from 'lucide-react';

interface HeaderProps {
  theme: 'dark' | 'light';
  toggleTheme: () => void;
  onOpenHistory: () => void;
  onOpenConfig: () => void;
  isScanning: boolean;
  activeTab: 'reconciler' | 'studio';
  onTabChange: (tab: 'reconciler' | 'studio') => void;
}

export const Header: React.FC<HeaderProps> = ({
  theme,
  toggleTheme,
  onOpenHistory,
  onOpenConfig,
  isScanning,
  activeTab,
  onTabChange,
}) => {
  return (
    <header
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '0.75rem 2rem',
        borderBottom: '1px solid var(--border-light)',
        background: 'var(--bg-card)',
        gap: '1rem',
        flexWrap: 'nowrap',
        zIndex: 50,
      }}
    >
      {/* Brand & Purpose */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
        <div
          style={{
            width: 34,
            height: 34,
            borderRadius: 'var(--radius-sm)',
            background: 'var(--accent-bg)',
            border: '1px solid var(--accent)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'var(--accent)',
            boxShadow: '0 0 12px var(--accent-glow)',
          }}
        >
          <Zap size={20} className={isScanning ? 'spinner' : ''} />
        </div>

        <div>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.45rem',
              fontWeight: 700,
              fontSize: '16px',
              letterSpacing: '-0.02em',
            }}
          >
            <span style={{ color: 'var(--accent)' }}>DRIVE</span>
            <span style={{ color: 'var(--text-primary)' }}>ARCHITECT</span>
            <span
              className="badge"
              style={{
                background: 'var(--accent-bg)',
                color: 'var(--accent)',
                border: '1px solid var(--accent-glow)',
              }}
            >
              Option A
            </span>
          </div>
          <div style={{ fontSize: '11px', color: 'var(--text-dim)', marginTop: '-1px' }}>
            Declarative Desired-State Reconciler
          </div>
        </div>
      </div>

      {/* Mode Switcher Tabs */}
      <div
        style={{
          display: 'flex',
          background: 'var(--bg-canvas)',
          borderRadius: 'var(--radius-full)',
          border: '1px solid var(--border-light)',
          padding: '3px',
          gap: '3px',
        }}
      >
        <button
          onClick={() => onTabChange('reconciler')}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.45rem',
            background: activeTab === 'reconciler' ? 'var(--accent)' : 'transparent',
            color: activeTab === 'reconciler' ? '#000' : 'var(--text-secondary)',
            border: 'none',
            borderRadius: 'var(--radius-full)',
            padding: '0.35rem 0.95rem',
            fontSize: '12.5px',
            fontWeight: 600,
            cursor: 'pointer',
            transition: 'all 0.15s ease',
          }}
        >
          <Zap size={13} />
          <span>Reconciler</span>
        </button>

        <button
          onClick={() => onTabChange('studio')}
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.45rem',
            background: activeTab === 'studio' ? 'var(--accent)' : 'transparent',
            color: activeTab === 'studio' ? '#000' : 'var(--text-secondary)',
            border: 'none',
            borderRadius: 'var(--radius-full)',
            padding: '0.35rem 0.95rem',
            fontSize: '12.5px',
            fontWeight: 600,
            cursor: 'pointer',
            transition: 'all 0.15s ease',
          }}
        >
          <FolderTree size={13} />
          <span>Template Studio</span>
        </button>
      </div>

      {/* Sovereign Connectivity Telemetry */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
        <div
          style={{
            display: 'flex',
            alignItems: 'center',
            gap: '0.4rem',
            padding: '0.25rem 0.65rem',
            borderRadius: 'var(--radius-full)',
            background: 'var(--bg-canvas)',
            border: '1px solid var(--border-light)',
            fontSize: '11.5px',
            color: 'var(--text-secondary)',
          }}
          title="Google Cloud Service Account Active"
        >
          <span
