import React from 'react';
import { Search, Play, RotateCw, Settings2, FolderTree, Database } from 'lucide-react';

interface CommandDeckProps {
  templateLink: string;
  rootLink: string;
  onOpenConfig: () => void;
  bypassCache: boolean;
  setBypassCache: (v: boolean) => void;
  onScan: () => void;
  onExecute: () => void;
  isScanning: boolean;
  isExecuting: boolean;
  hasPlan: boolean;
}

export const CommandDeck: React.FC<CommandDeckProps> = ({
  templateLink,
  rootLink,
  onOpenConfig,
  bypassCache,
  setBypassCache,
  onScan,
  onExecute,
  isScanning,
  isExecuting,
  hasPlan,
}) => {
  // Extract folder ID or display short preview
  const getShortId = (url: string) => {
    const match = url.match(/\/folders\/([a-zA-Z0-9_-]+)/);
    if (match) return match[1].slice(0, 10) + '...';
    if (url.length > 15) return url.slice(0, 10) + '...';
    return url || 'Not set';
  };

  return (
    <section className="card" style={{ padding: '1.25rem 1.5rem' }}>
      <div
        style={{
          display: 'flex',
          alignItems: 'center',
          justifyContent: 'space-between',
          flexWrap: 'wrap',
          gap: '1rem',
        }}
      >
        {/* Left: Compact Target Anchors */}
        <div style={{ display: 'flex', alignItems: 'center', gap: '0.85rem', flexWrap: 'wrap' }}>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.45rem',
              padding: '0.35rem 0.75rem',
              borderRadius: 'var(--radius-sm)',
              background: 'var(--bg-canvas)',
              border: '1px solid var(--border-light)',
            }}
          >
            <FolderTree size={14} style={{ color: 'var(--accent)' }} />
            <span style={{ fontSize: '11px', color: 'var(--text-dim)', textTransform: 'uppercase', fontWeight: 600 }}>
              Archetype:
            </span>
            <span style={{ fontSize: '12.5px', fontWeight: 600, color: 'var(--accent)' }}>
              Entropy 0
            </span>
            <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}>
              ({getShortId(templateLink)})
            </span>
          </div>

          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.45rem',
              padding: '0.35rem 0.75rem',
              borderRadius: 'var(--radius-sm)',
              background: 'var(--bg-canvas)',
              border: '1px solid var(--border-light)',
            }}
          >
            <FolderTree size={14} style={{ color: 'var(--info)' }} />
            <span style={{ fontSize: '11px', color: 'var(--text-dim)', textTransform: 'uppercase', fontWeight: 600 }}>
              Data Root:
            </span>
            <span style={{ fontSize: '12.5px', fontWeight: 600, color: 'var(--info)' }}>
              Testaments
            </span>
            <span style={{ fontSize: '11px', color: 'var(--text-tertiary)', fontFamily: 'var(--font-mono)' }}>
              ({getShortId(rootLink)})
            </span>
          </div>

          <button
            onClick={onOpenConfig}
            className="btn subtle"
            style={{ padding: '0.35rem 0.65rem', fontSize: '12px' }}
            title="Configure Target Folders"

