import React from 'react';
import { Zap, Moon, Sun, History, HardDrive, Settings2, FolderTree, Compass } from 'lucide-react';

interface HeaderProps {
  theme: 'dark' | 'light';
  toggleTheme: () => void;
  onOpenHistory: () => void;
  onOpenConfig: () => void;
  isScanning: boolean;
  activeTab: 'reconciler' | 'navigator' | 'studio';
  onTabChange: (tab: 'reconciler' | 'navigator' | 'studio') => void;
  mockMode: boolean;
  onToggleMockMode: () => void;
  onResetMockData: () => void;
}

export const Header: React.FC<HeaderProps> = ({
  theme,
  toggleTheme,
  onOpenHistory,
  onOpenConfig,
  isScanning,
  activeTab,
  onTabChange,
  mockMode,
  onToggleMockMode,
  onResetMockData,
}) => {
  return (
    <header
      style={{
        display: 'flex',
        alignItems: 'center',
        justifyContent: 'space-between',
        padding: '0.75rem 2rem',
        borderBottom: '1px solid var(--border-light)',
        background: 'var(--bg-card)',
        gap: '1rem',
        flexWrap: 'nowrap',
        zIndex: 50,
      }}
    >
      {/* Brand & Purpose */}
      <div style={{ display: 'flex', alignItems: 'center', gap: '0.75rem' }}>
        <div
          style={{
            width: 34,
            height: 34,
            borderRadius: 'var(--radius-sm)',
            background: 'var(--accent-bg)',
            border: '1px solid var(--accent)',
            display: 'flex',
            alignItems: 'center',
            justifyContent: 'center',
            color: 'var(--accent)',
            boxShadow: '0 0 12px var(--accent-glow)',
          }}
        >
          <Zap size={20} className={isScanning ? 'spinner' : ''} />
        </div>

        <div>
          <div
            style={{
              display: 'flex',
              alignItems: 'center',
              gap: '0.45rem',
              fontWeight: 700,
              fontSize: '16px',
              letterSpacing: '-0.02em',
            }}
          >
            <span style={{ color: 'var(--accent)' }}>DRIVE</span>
            <span style={{ color: 'var(--text-primary)' }}>ARCHITECT</span>
            <span
              className="badge"
              style={{
                background: 'var(--accent-bg)',
                color: 'var(--accent)',
                border: '1px solid var(--accent-glow)',
              }}
            >
              Option A
            </span>
          </div>
