        className="btn primary"
        style={{
          padding: '0.5rem 1.15rem',
          fontSize: '12.5px',
          fontWeight: 700,
          background: 'var(--accent)',
          color: '#000',
          border: 'none',
          borderRadius: 'var(--radius-sm)',
          boxShadow: '0 0 14px var(--accent-glow)',
