  const handleSlugChange = (val: string) => {
    setAutoSlug(false);
    setSlug(val.toLowerCase().replace(/[^a-z0-9_]/g, '_'));
  };

  const handleSubmit = async (e: React.FormEvent) => {
    e.preventDefault();
    const cleanId = slug.trim() || name.toLowerCase().replace(/[^a-z0-9_]/g, '_');
