              }}
            />
          </div>

          {/* Group Selector */}
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: 'var(--text-dim)', marginBottom: '0.4rem' }}>
              Destination Group (Outliner Taxonomy)
            </label>
            <select
              value={groupId}
              onChange={(e) => setGroupId(e.target.value)}
              style={{
                width: '100%',
                minHeight: '44px',
                padding: '0.65rem 0.85rem',
                borderRadius: 'var(--radius-sm)',
                background: 'var(--bg-canvas)',
                border: '1px solid var(--border-mid)',
                color: 'var(--text-primary)',
                fontSize: '13.5px',
                outline: 'none',
                cursor: 'pointer',
              }}
            >
              {availableGroups.map((g) => (
                <option key={g.group_id} value={g.group_id}>
                  {g.group_name}
                </option>
              ))}
            </select>
          </div>

          {/* Template Archetype (Fixed) */}
          <div>
            <label style={{ display: 'block', fontSize: '12px', fontWeight: 600, color: 'var(--text-dim)', marginBottom: '0.4rem' }}>
              Template Archetype
            </label>
            <div
              style={{
                minHeight: '40px',
                padding: '0.55rem 0.85rem',
                borderRadius: 'var(--radius-sm)',
                background: 'var(--bg-canvas)',
                border: '1px solid var(--border-light)',
                display: 'flex',
                alignItems: 'center',
                gap: '0.4rem',
                fontSize: '13px',
                color: 'var(--accent)',
                fontWeight: 600,
              }}
            >
              <Folder size={14} />
              <span>{templateName}</span>
              <span style={{ fontSize: '10.5px', color: 'var(--text-dim)', marginLeft: 'auto' }}>
                All subfolders auto-stamped
              </span>
            </div>
          </div>

          {/* Action Buttons */}
          <div style={{ display: 'flex', alignItems: 'center', justifyContent: 'flex-end', gap: '0.75rem', marginTop: '0.5rem' }}>
            <button
              type="button"
              onClick={onClose}
              disabled={isSubmitting}
              className="btn subtle"
              style={{ padding: '0.5rem 1rem', fontSize: '13px' }}
            >
              Cancel
            </button>
            <button
              type="submit"
              disabled={isSubmitting || !name.trim()}
              className="btn primary"
              style={{
                padding: '0.55rem 1.25rem',
                fontSize: '13px',
                fontWeight: 600,
                background: 'var(--accent)',
                color: '#000',
                border: 'none',
                boxShadow: '0 0 12px var(--accent-glow)',
              }}
