                              style={{
                                color: isSelected ? 'var(--accent)' : 'var(--text-dim)',
                                flexShrink: 0,
                              }}
                            />
                            <span
                              style={{
                                fontSize: '12.5px',
                                fontWeight: isSelected ? 600 : 400,
                                whiteSpace: 'nowrap',
                                overflow: 'hidden',
                                textOverflow: 'ellipsis',
                              }}
                            >
                              {ep.target_root_name}
                            </span>
                          </div>

                          {exceptionCount > 0 ? (
                            <span
                              className="badge badge-rename"
                              style={{
                                fontSize: '9.5px',
                                padding: '1px 5px',
                                flexShrink: 0,
                                display: 'inline-flex',
                                alignItems: 'center',
                                gap: '0.2rem',
                              }}
                            >
                              <AlertCircle size={9} /> {exceptionCount}
                            </span>
                          ) : (
                            <CheckCircle2 size={12} style={{ color: 'var(--success)', flexShrink: 0 }} />
                          )}
                        </button>
                      );
                    })
                  )}
                </div>
              )}
            </div>
          );
        })}
      </div>
    </aside>
  );
};

