1	import { TableRecord } from '../types';
2	import { HierarchicalRecord, HeadingSortCandidate, extractFirstRelationId } from './headingSort';
3	
4	export interface BranchDropResult {
5	  updatedField?: { slug: string; value: any };
6	  reorderedRecords: TableRecord[];
7	}
8	
9	/**
10	 * Resolves record reordering and branch migration when dragging & dropping rows.
11	 */
12	export function resolveBranchDrop(
13	  draggedItem: HierarchicalRecord,
14	  targetItem: HierarchicalRecord,
15	  records: TableRecord[],
16	  headingSortActive: boolean,
17	  activeCandidate: HeadingSortCandidate | null,
18	  dragPosition: 'top' | 'bottom' | null
19	): BranchDropResult {
20	  const draggedId = draggedItem.record.id;
21	  const targetId = targetItem.record.id;
22	
23	  // 1. Calculate reordered records list
24	  const nextRecords = [...records];
