@app.post("/api/drive/move_folder")
def move_folder_endpoint(req: MoveFolderRequest):
    """Moves a folder to a new parent directory (Optimistic / Decoupled PK Pattern)."""
    if GLOBAL_MOCK_MODE or (req.folder_id and "mock" in req.folder_id):
        res = mock_store.move_folder(req.folder_id, req.new_parent_id)
        return {"success": True, "folder": res, "mock_mode": True}

    fid = drive_ops.extract_folder_id_from_url(req.folder_id)
    new_pid = drive_ops.extract_folder_id_from_url(req.new_parent_id)
    if not fid or not new_pid:
        raise HTTPException(status_code=400, detail="Invalid folder ID or target parent ID")
    try:
        meta = drive_ops.get_file_metadata(fid, fields="id, parents")
        old_parents = ",".join(meta.get("parents", []))
        service = drive_ops.get_thread_safe_drive_service()
        res = service.files().update(
            fileId=fid,
            addParents=new_pid,
            removeParents=old_parents,
            fields="id, name, parents",
            supportsAllDrives=True,
        ).execute()
        db.clear_folder_tree_cache()
        return {"success": True, "folder": res}
    except Exception as e:
        raise HTTPException(status_code=500, detail=f"Failed to move folder: {str(e)}")

