# core/config.py
"""
Configuration loader for Arc-2-Neo-Drives.
Loads credentials and application parameters from secret.tomb / secrets.toml.
"""

import os
from pathlib import Path
from typing import Any, Dict, Optional
import toml

# Candidate search paths for the secret file
DEFAULT_CANDIDATE_PATHS = [
    Path(r"D:\My Drive\Blue AI\secret.tomb"),
    Path(__file__).resolve().parent.parent / "secret.tomb",
    Path(__file__).resolve().parent.parent / "secrets.toml",
    Path(r"D:\My Drive\Blue AI\Arc-2-Neo-Drives\secret.tomb"),
]

# Database storage path
BASE_DIR = Path(__file__).resolve().parent.parent
DATA_DIR = BASE_DIR / "data"
DEFAULT_DB_PATH = DATA_DIR / "neo_drive.db"


def find_secret_path() -> Optional[Path]:
    """Find the first existing secret file path."""
    for p in DEFAULT_CANDIDATE_PATHS:
        if p.exists() and p.is_file():
            return p
    return None


class Config:
    def __init__(self, secret_path: Optional[Path] = None):
        self.secret_path = secret_path or find_secret_path()
        self.raw_data: Dict[str, Any] = {}
        self.load()

    def load(self):
        """Loads and parses the secret configuration file."""
        if not self.secret_path or not self.secret_path.exists():
            # Gracefully handle missing secret file
            self.raw_data = {}
            return

        try:
            with open(self.secret_path, "r", encoding="utf-8") as f:
                self.raw_data = toml.load(f)
        except Exception as e:
            raise RuntimeError(f"Failed to read secret config at {self.secret_path}: {e}")

    @property
    def gcp_service_account(self) -> Dict[str, Any]:
        """Returns the GCP Service Account credentials dict."""
        return self.raw_data.get("gcp_service_account", {})

    @property
    def app_config(self) -> Dict[str, Any]:
        """Returns application configuration parameters."""
        return self.raw_data.get("app_config", {})

    @property
    def passcode(self) -> str:
        """Returns the configured security passcode."""
        return self.app_config.get("passcode", "HazardOn!")

    @property
    def fandom_template_id(self) -> Optional[str]:
        """Returns the fandom template folder or file ID."""
        return self.app_config.get("fandom_template") or "1qPYOlZ3-LlnfiBRorXUnNa_0yVZcILvM"

    @property
    def default_template_url(self) -> str:
        return "https://drive.google.com/drive/folders/1qPYOlZ3-LlnfiBRorXUnNa_0yVZcILvM"

    @property
    def default_root_url(self) -> str:
        return "https://drive.google.com/drive/folders/14J8QBCqdSQOPerLBIaR2jLyYhZ4WbJUA"

    @property
    def tag_folders(self) -> list:
        """Returns the list of configured tag folders."""
        return self.app_config.get("tag_folders", [])

    @property
    def db_path(self) -> Path:
        """Returns the SQLite database path."""
        DATA_DIR.mkdir(parents=True, exist_ok=True)
        return DEFAULT_DB_PATH

    def verify_passcode(self, candidate: str) -> bool:
        """Deterministic constant-time-like passcode verification."""
        if not self.passcode:
            return True
        return candidate.strip() == self.passcode.strip()


