for a in actual_c24:
    p = a["child_of"]
    subs_by_parent.setdefault(p, []).append(a)

def match_level(parent_id, expected_dict, rel_path):
    actual_list = subs_by_parent.get(parent_id, [])
    matched_actual_ids = set()

    for exp_name, exp_node in expected_dict.items():
        exp_aliases = set(exp_node.get("aliases", []))
        exp_aliases.add(exp_name.lower())
        child_path = f"{rel_path}/{exp_name}"

        # 1. Match by src_id or alias
        act = None
        for a in actual_list:
            if a["drive_id"] in matched_actual_ids:
                continue
            a_src = (a.get("src_id") or "").lower()
            a_name = a["name"].lower()
            if a_src in exp_aliases or a_name in exp_aliases or a["name"] == exp_name:
                act = a
                break

        if act:
            matched_actual_ids.add(act["drive_id"])
            if act["name"] != exp_name:
                print(f" [RENAME] {child_path}: '{act['name']}' -> '{exp_name}' (ID: {act['drive_id']})")
            else:
                print(f" [MATCH]  {child_path}: In sync! (ID: {act['drive_id']})")

            # Check deeper children
            if exp_node.get("subfolders"):
                match_level(act["drive_id"], exp_node["subfolders"], child_path)
        else:
            print(f" [CREATE] {child_path}: Missing required folder")

match_level("c24", expected, "C24")

