interface EntityFolderCardProps {
  entityPlan: EntityPlan;
  onFixEntity: (entityPlan: EntityPlan) => void;
  isExecuting: boolean;
  isFullWidth?: boolean;
  viewMode?: 'all' | 'conflict' | 'perfected';
  onRenameEntity?: (entityId: string, newName: string) => Promise<void>;
}

interface TreeNode {
  item: ActionItem;
  path: string;
  name: string;
  children: TreeNode[];
}

function buildEntityTree(items: ActionItem[], viewMode: 'all' | 'conflict' | 'perfected' = 'all'): TreeNode[] {
  let subItems = items.filter((i) => {
    const parts = i.relative_path.split('/').filter(Boolean);
    return parts.length > 2;
  });

  if (viewMode === 'conflict') {
    const conflictPaths = new Set(
      subItems.filter((i) => i.action_type !== 'MATCH' && i.action_type !== 'CUSTOM').map((i) => i.relative_path)
    );
    // Show only true conflict folders or folders containing conflict descendants
    subItems = subItems.filter((i) => {
      if (i.action_type !== 'MATCH' && i.action_type !== 'CUSTOM') return true;
      return Array.from(conflictPaths).some((cp) => cp.startsWith(i.relative_path + '/'));
    });
  } else if (viewMode === 'perfected') {
    // Show non-conflict subfolders (MATCH or CUSTOM)
    subItems = subItems.filter((i) => i.action_type === 'MATCH' || i.action_type === 'CUSTOM');
  }

